import{Ct as e,Mt as t,at as n,it as r,nt as i,o as a,ot as o,st as s,tt as c,yt as l}from"./chunks/framework.B-d2E8F-.js";var u=a({__name:`CliRemoteHero`,setup(n){return(n,r)=>{let a=e(`TermWindow`);return l(),i(a,{title:`texra login`,"aria-label":`Sign in once and use remote agents by name from the terminal`},{default:t(()=>[...r[0]||=[c(`div`,{class:`mk-term-prompt`},[c(`span`,{class:`mk-term-sigil`},`$`),c(`span`,{class:`mk-term-cmd`},`texra login`)],-1),c(`div`,{class:`crm-block`},[c(`div`,{class:`crm-dim`},` Pick a provider: GitHub / Google → browser opens `),c(`div`,{class:`crm-ok`},`Signed in as ada@lab.edu.`)],-1),c(`div`,{class:`mk-term-prompt crm-beat`},[c(`span`,{class:`mk-term-sigil`},`$`),c(`span`,{class:`mk-term-cmd`},`texra agents show search`)],-1),c(`div`,{class:`crm-block`},[c(`div`,null,[c(`span`,{class:`crm-k`},`name:`),o(` search`)]),c(`div`,null,[c(`span`,{class:`crm-k`},`category:`),o(` toolUse`)]),c(`div`,null,[c(`span`,{class:`crm-k`},`source:`),c(`span`,{class:`crm-hot`},` remote`)])],-1),c(`div`,{class:`mk-term-prompt crm-beat`},[c(`span`,{class:`mk-term-sigil`},`$`),c(`span`,{class:`mk-term-cmd`},[o(`texra chat `),c(`span`,{class:`mk-term-flag`},`--agent`),o(` search`)])],-1),c(`div`,{class:`crm-note`},` runs like any local agent — same chat, same run history `,-1)]]),_:1})}}},[[`__scopeId`,`data-v-ee609d7c`]]),d=JSON.parse(`{"title":"Remote agents","description":"","frontmatter":{},"headers":[],"relativePath":"guide/remote-agents.md","filePath":"guide/remote-agents.md"}`),f=Object.assign({name:`guide/remote-agents.md`},{setup(t){return(t,i)=>{let a=e(`DropdownMenu`),d=e(`FeatureCards`);return l(),r(`div`,null,[i[0]||=n(`<h1 id="remote-agents" tabindex="-1">Remote agents <a class="header-anchor" href="#remote-agents" aria-label="Permalink to “Remote agents”">​</a></h1><p>Remote agents are cloud-hosted agents maintained by the TeXRA team. They add specialized capabilities to TeXRA and receive updates without an extension update.</p><h2 id="what-are-remote-agents" tabindex="-1">What are remote agents? <a class="header-anchor" href="#what-are-remote-agents" aria-label="Permalink to “What are remote agents?”">​</a></h2><p>Remote agents are pre-configured agents hosted in the cloud that you can run directly from TeXRA. Unlike built-in agents, they:</p><ul><li>Receive updates automatically, without an extension update</li><li>Provide specialized capabilities for specific research domains</li><li>Load on demand, so the extension stays small</li></ul><h2 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting started”">​</a></h2><h3 id="_1-sign-in-to-texra" tabindex="-1">1. Sign in to TeXRA <a class="header-anchor" href="#_1-sign-in-to-texra" aria-label="Permalink to “1. Sign in to TeXRA”">​</a></h3><p>Remote agents require a TeXRA account:</p><ol><li>Open the Command Palette (<code>Ctrl+Shift+P</code> / <code>Cmd+Shift+P</code>)</li><li>Run <strong>TeXRA: Sign In</strong></li><li>Choose a sign-in method (GitHub or Google)</li><li>Complete the sign-in flow in your browser</li><li>Return to VS Code once signed in</li></ol><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>To check your sign-in status at any time, run <strong>TeXRA: View Profile</strong> from the Command Palette.</p></div><h3 id="_2-browse-available-agents" tabindex="-1">2. Browse available agents <a class="header-anchor" href="#_2-browse-available-agents" aria-label="Permalink to “2. Browse available agents”">​</a></h3><p>Once signed in, browse remote agents from the Agents tab:</p><ol><li>Open the Command Palette</li><li>Run <strong>TeXRA: Show Agents</strong> to open the Agents tab in Settings</li><li>Select a remote agent in the list to see its details</li><li>Select <strong>Show in agent selector</strong> to add it to your agent selector</li></ol><p>Your email and access level sit on the Account &amp; Usage tab (<strong>TeXRA: View Profile</strong>).</p><p>The selected agent appears in the main TeXRA view alongside your built-in agents.</p><h3 id="_3-use-remote-agents" tabindex="-1">3. Use remote agents <a class="header-anchor" href="#_3-use-remote-agents" aria-label="Permalink to “3. Use remote agents”">​</a></h3><p>Remote agents work like built-in agents:</p><ol><li>Open the TeXRA view (select the TeXRA icon in the Secondary Side Bar)</li><li>Select your remote agent from the agent dropdown</li><li>Choose your input file and model</li><li>Select <strong>Run</strong> to start the agent</li></ol><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Remote agents carry a cloud icon (☁️) in the agent selector to set them apart from local agents.</p></div><p>The agent dropdown is a single flat list with no Local/Remote headers; remote agents are told apart only by the trailing cloud icon (tooltip: Remote agent, prompts loaded from cloud), and a <strong>Browse all agents…</strong> entry at the end opens Settings → Agents:</p>`,20),s(a,{label:`Agent`,value:`search`,valueIcon:`cloud`,maxWidth:`320px`,groups:[{items:[{name:`polish`,icon:`sparkle`},{name:`correct`,icon:`pencil`},{name:`search`,icon:`cloud`,badge:`in use`,badgeVariant:`accent`,active:!0},{name:`simplifier`,icon:`cloud`},{name:`orchestrator`,icon:`cloud`}]}]}),i[1]||=c(`p`,{class:`hero-caption`},[o(`The agent dropdown: one flat list where remote agents (`),c(`code`,null,`search`),o(`, `),c(`code`,null,`simplifier`),o(`, `),c(`code`,null,`orchestrator`),o(`) carry a cloud marker that sets them apart from local agents like `),c(`code`,null,`polish`),o(` and `),c(`code`,null,`correct`),o(`.`)],-1),i[2]||=c(`p`,null,`None of this is VS Code-only. The whole loop works from a terminal too:`,-1),s(u),i[3]||=n(`<p class="hero-caption">Sign in once and remote agents resolve by name everywhere: <code>agents show</code> reports <code>source: remote</code>, and <code>texra chat --agent search</code> runs it like any local agent.</p><h2 id="remote-agent-access" tabindex="-1">Remote agent access <a class="header-anchor" href="#remote-agent-access" aria-label="Permalink to “Remote agent access”">​</a></h2><p>Signed-in researchers, academics, and technical writers can use specialized remote agents for academic research and professional writing. Signing in only unlocks the hosted agent catalog. Remote agents still run on your own credential, the same provider API key or subscription as your built-in agents. Access includes:</p><ul><li><strong>Specialized domain agents</strong>: Agents tailored for specific research fields (mathematics, computer science, physics, and others)</li><li><strong>Advanced reasoning capabilities</strong>: Multi-step analysis and complex document processing</li><li><strong>Beta features</strong>: Early access to experimental agents and capabilities</li><li><strong>Priority improvements</strong>: Your feedback directly influences agent development</li></ul>`,4),s(d,{min:`220px`,cards:[{icon:`mortar-board`,title:`Specialized domain agents`,desc:`Agents tailored for specific research fields.`,chips:[{text:`mathematics`,variant:`info`},{text:`CS`,variant:`info`},{text:`physics`,variant:`info`}]},{icon:`pulse`,title:`Advanced reasoning`,desc:`Multi-step analysis and complex document processing.`,chips:[{text:`multi-step`,variant:`neutral`}]},{icon:`sparkle`,title:`Beta features`,tag:`Early access`,tagVariant:`accent`,desc:`Early access to experimental agents and capabilities.`},{icon:`comment-discussion`,title:`Priority improvements`,desc:`Your feedback directly influences agent development.`,chips:[{text:`your feedback`,variant:`neutral`}]}]}),i[4]||=n(`<p class="hero-caption">What remote agent access gets you: domain-specific agents, advanced multi-step reasoning, early access to beta agents, and a direct line into how agents evolve.</p><p>Current remote agents include <code>search</code> (literature discovery), <code>simplifier</code> (code and writing simplification), and <code>orchestrator</code> (multi-agent coordination). Read the <a href="./built-in-agents.html#remote-agents">remote agents section of the built-in agents guide</a> for details on each.</p><p>Different agents may be available to different research groups, depending on their domain and needs.</p><h3 id="requesting-access" tabindex="-1">Requesting access <a class="header-anchor" href="#requesting-access" aria-label="Permalink to “Requesting access”">​</a></h3><p>Remote agent access is available to active researchers, academics, and technical writers. To request it:</p><ol><li><strong>Sign in</strong> to TeXRA using your institutional or professional email</li><li><strong>Contact us</strong> at <a href="mailto:contact@texra.ai" target="_blank" rel="noreferrer">contact@texra.ai</a> with: <ul><li>Your name and affiliation</li><li>A brief description of your research area</li><li>How you plan to use remote agents</li></ul></li></ol><p>We review each request and grant access within 1-2 business days.</p><div class="tip custom-block"><p class="custom-block-title">Free for researchers</p><p>TeXRA supports academic research. Remote agent access is <strong>free for qualifying researchers and students</strong>: there is no charge for the hosted agent catalog. Model calls made by those agents are still billed to your own provider account or subscription.</p></div><h2 id="managing-your-account" tabindex="-1">Managing your account <a class="header-anchor" href="#managing-your-account" aria-label="Permalink to “Managing your account”">​</a></h2><h3 id="view-your-profile" tabindex="-1">View your profile <a class="header-anchor" href="#view-your-profile" aria-label="Permalink to “View your profile”">​</a></h3><p>To check your account status:</p><ol><li>Open the Command Palette</li><li>Run <strong>TeXRA: View Profile</strong></li><li>View your email and access level on the Account &amp; Usage tab</li></ol><p>Run <strong>TeXRA: Show Agents</strong> to browse the remote agents available to you.</p><h3 id="sign-out" tabindex="-1">Sign out <a class="header-anchor" href="#sign-out" aria-label="Permalink to “Sign out”">​</a></h3><p>To sign out of your TeXRA account:</p><ol><li>Open the Command Palette</li><li>Run <strong>TeXRA: Sign Out</strong></li><li>Confirm sign out</li></ol><p>Your local agents continue to work after signing out. Only remote agents become unavailable until you sign in again.</p><h2 id="frequently-asked-questions" tabindex="-1">Frequently asked questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to “Frequently asked questions”">​</a></h2><h3 id="do-i-need-to-sign-in-to-use-texra" tabindex="-1">Do I need to sign in to use TeXRA? <a class="header-anchor" href="#do-i-need-to-sign-in-to-use-texra" aria-label="Permalink to “Do I need to sign in to use TeXRA?”">​</a></h3><p>No. TeXRA works fully offline with built-in agents. Sign in only if you want remote agents from the cloud.</p><h3 id="are-remote-agents-slower-than-built-in-agents" tabindex="-1">Are remote agents slower than built-in agents? <a class="header-anchor" href="#are-remote-agents-slower-than-built-in-agents" aria-label="Permalink to “Are remote agents slower than built-in agents?”">​</a></h3><p>Remote agents perform similarly to built-in agents. The agent configuration is loaded from the cloud, but the model runs with your configured API keys, as with built-in agents.</p><h3 id="can-i-use-remote-agents-offline" tabindex="-1">Can I use remote agents offline? <a class="header-anchor" href="#can-i-use-remote-agents-offline" aria-label="Permalink to “Can I use remote agents offline?”">​</a></h3><p>No. Remote agents require an internet connection to load their configurations. For offline work, use built-in agents instead.</p><h3 id="what-happens-to-my-documents" tabindex="-1">What happens to my documents? <a class="header-anchor" href="#what-happens-to-my-documents" aria-label="Permalink to “What happens to my documents?”">​</a></h3><p>Your documents are never uploaded to TeXRA servers. Remote agents only load their configuration (prompts and settings) from the cloud. All document processing happens locally using your own API keys.</p><h3 id="can-i-create-my-own-remote-agents" tabindex="-1">Can I create my own remote agents? <a class="header-anchor" href="#can-i-create-my-own-remote-agents" aria-label="Permalink to “Can I create my own remote agents?”">​</a></h3><p>Currently, remote agents are maintained by the TeXRA team. If you have ideas for new agents or want to share your custom agents with the community, contact us at <a href="mailto:contact@texra.ai" target="_blank" rel="noreferrer">contact@texra.ai</a>.</p><h3 id="how-do-i-disable-remote-agents" tabindex="-1">How do I disable remote agents? <a class="header-anchor" href="#how-do-i-disable-remote-agents" aria-label="Permalink to “How do I disable remote agents?”">​</a></h3><p>Remote agents are available only while you are signed in. To stop using them, sign out; your built-in agents keep working. (In the CLI, run <code>texra auth logout</code>; in the VS Code extension, use the sign-out action in the account menu.)</p><h2 id="need-help" tabindex="-1">Need help? <a class="header-anchor" href="#need-help" aria-label="Permalink to “Need help?”">​</a></h2><p>If you run into issues with remote agents or have questions about access:</p><ul><li><strong>Email</strong>: <a href="mailto:contact@texra.ai" target="_blank" rel="noreferrer">contact@texra.ai</a></li><li><strong>Documentation</strong>: <a href="https://texra.ai/guide" target="_blank" rel="noreferrer">texra.ai/guide</a></li></ul><p>We typically respond within 24-48 hours.</p>`,34)])}}});export{d as __pageData,f as default};